import{_ as a,o as e,c as l,a2 as r}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"篇103｜境界細分・感元境・万族各族群差別化修練体系","description":"","frontmatter":{"title":"篇103｜境界細分・感元境・万族各族群差別化修練体系","no":103,"module":1,"tags":["境界","感元境","万族","差异化修炼","覆盖度"],"related":["14-修炼境界统一划分","50-万族谱系总览","52-异族分类与共生","10-三百套本源修炼体系总览"]},"headers":[],"relativePath":"ja/0103_模块1-感元境-万族差异化修炼体系.md","filePath":"ja/0103_模块1-感元境-万族差异化修炼体系.md"}'),d={name:"ja/0103_模块1-感元境-万族差异化修炼体系.md"};function i(h,t,o,n,_,s){return e(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="篇103-感元境-万族各族群差別化修練体系" tabindex="-1">篇103｜感元境：万族各族群差別化修練体系 <a class="header-anchor" href="#篇103-感元境-万族各族群差別化修練体系" aria-label="Permalink to &quot;篇103｜感元境：万族各族群差別化修練体系&quot;">​</a></h1><blockquote><p>所属モジュール：モジュール一・境界深度細分｜対地基文書：14、50、52、10</p></blockquote><h2 id="序論-万族は万種の人族ではない" tabindex="-1">序論：万族は万種の人族ではない <a class="header-anchor" href="#序論-万族は万種の人族ではない" aria-label="Permalink to &quot;序論：万族は万種の人族ではない&quot;">​</a></h2><p>衡元宙（ヘン・ユアンジョウ：本源的均衡宇宙）の万族共和公理は、概念上最も誤解されやすい：万族は「万種の人族」ではなく、炭素・エネルギー・機械・意識・混合の五大系譜に属する無数の生命形態である。九境の起点たる感元境は、「一境万法」の姿勢でこの多様性を受け止めねばならない——同じ感元境と呼ばれながら、獣族の「感知」は嗅覚と直感であり、霊族の「感知」はエネルギー共鳴であり、機族の「感知」はデータスキャンである。</p><p>単一の種族の基準で万族を測ること自体、傲慢なエネルギー浪費である。本文は《万族谱系総覧》（文書50）と《異族分類と共生》（文書52）に依拠し、万族の感元境における差別化修練体系を展開する。</p><p>六大頂層公理は万族差別化の立法根基である：反略奪主義公理——各族は宇宙循環にのみエネルギーを求め、決して互いの本源を吞噬しない；万族共和公理——平等な進化資格は系譜を問わない；集団昇維公理——各族の天賦は文明に恩返しせねばならず、大材小用を杜绝する；因果自律公理——跨種族共修は彼族の因果境界を尊重する；法則優先公理——万族差別化修練体系の法則枠組は安定して自己整合的で、脚本の都合で設定改変せず、無限拡張しても崩壊しない。衆生全員無限均等法則は人人が基礎無限の力を自带することを確立し、佛系・怠惰な者は保底基礎無限を保有し時代に淘汰されず、卷王と少年至尊はより高位の無限を重畳でき、無限本源は人人が自带し、略奪は自然に意義を失う。</p><h2 id="一、五大系譜の感元境差異" tabindex="-1">一、五大系譜の感元境差異 <a class="header-anchor" href="#一、五大系譜の感元境差異" aria-label="Permalink to &quot;一、五大系譜の感元境差異&quot;">​</a></h2><p>文書53の万族五大分類（炭基物質族、能量凝集族、機械構造族、意識信息族、混合変異族）に依拠し、各族の感元境における起点は先天的に異なる：</p><table tabindex="0"><thead><tr><th>系譜</th><th>代表族群</th><th>感元境特徴</th><th>適配体系傾向</th></tr></thead><tbody><tr><td>炭基物質族</td><td>Rén Zú、兽族、木族</td><td>感知の起点は肉身と五感に依り、エネルギー感知意識の樹立に時間を要する</td><td>生命循環体系、推演迭代体系</td></tr><tr><td>能量凝集族</td><td>霊族、元素生命</td><td>先天的にエネルギー体であり、「感知」はほぼ本能、基礎を飛ばして直接凝縮しやすい</td><td>空間法理調度体系、本源推演類</td></tr><tr><td>機械構造族</td><td>機族、機械生命</td><td>データ化方式でエネルギーを「感知」し、精度高いが直感に乏しい</td><td>応用工程類、推演迭代体系</td></tr><tr><td>意識信息族</td><td>意識体、高次元存在</td><td>感知そのものが意識活動であり、感元境とその本源形態が高度に一致</td><td>意識昇維類</td></tr><tr><td>混合変異族</td><td>跨位面混血、奇特生命</td><td>起点差異が極めて大きく、個別評価を要する</td><td>体系兼容性評価を優先</td></tr></tbody></table><p>差異は尊重されねばならないが、「優越種族」を作るために用いられてはならない：霊族は感知速いが肉身の承载弱く；機族は精度高いが霊性進化は難しく；意識族は起点高いが、物質位面を離脱後に補うべき課題がより多い。感元境の統一基準（文書14）は「感知-吸収-弁識」の実質的能力を評価し、感知の具体的形式ではない——これが「重実質軽名称」原則の種族版である。</p><h2 id="二、差別化路線-万族各に其の路あり、路路本源に通ず" tabindex="-1">二、差別化路線：万族各に其の路あり、路路本源に通ず <a class="header-anchor" href="#二、差別化路線-万族各に其の路あり、路路本源に通ず" aria-label="Permalink to &quot;二、差別化路線：万族各に其の路あり、路路本源に通ず&quot;">​</a></h2><ul><li>兽族路線：身体直感を錨とし、先に体感を練り次に感応を練る、感元境即「血脈中のエネルギー言語を喚起する」</li><li>木族路線：生長リズムを錨とし、慢速安定吸収、感元境は樹年輪と同期、一境百年修して急がず</li><li>霊族路線：エネルギー共鳴を錨とし、感元境は「収斂」を重んじ「開放」ではなく、先天感知の過負荷を制御するを学ぶ</li><li>機族路線：データ校正を錨とし、エネルギー感知を再計算可能モデルに転換、感元境即「センサーを校正する」</li><li>意識族路線：意識澄明を錨とし、感元境即「意識の着地」、物質位面の言語で感知を表現するを学ぶ</li></ul><p>各路線は同一の境界認証体系に通じるが、認証の背後には各自の原生ロジックがある。これこそ万族本源双方向循環の基層形態である：各族は異なる方式で宇宙から汲み、異なる方式で文明に還し、循環は決して単方向ではない。</p><h2 id="三、跨種族共修-導師網の真の意義" tabindex="-1">三、跨種族共修：導師網の真の意義 <a class="header-anchor" href="#三、跨種族共修-導師網の真の意義" aria-label="Permalink to &quot;三、跨種族共修：導師網の真の意義&quot;">​</a></h2><p>万族差別化は各修各を意味せず、跨種族共修こそ感元境最も価値ある場面である：</p><ul><li>跨種族導師：霊族導師が兽族学员のエネルギー感知を校正し、Rén Zú導師が霊族学员の肉身承載を理解するを助ける——導師網（文書10）の本質は文明層面の経験流動</li><li>兼容評価：体系兼容性評価機制が混血個体と奇特生命に個別方案を提供し、「種族でラベルを貼る」を杜绝</li><li>平等認証：境界認証と資源分配はデータと貢献のみを認め、出身を認めず；万族少年至尊（篇102）も双路線機制を共有</li></ul><h2 id="四、対比-種族狭隘は普惠体系の天井" tabindex="-1">四、対比：種族狭隘は普惠体系の天井 <a class="header-anchor" href="#四、対比-種族狭隘は普惠体系の天井" aria-label="Permalink to &quot;四、対比：種族狭隘は普惠体系の天井&quot;">​</a></h2><p>これこそ「Táng Luó上限」の万族次元における直接的表現である：旧時代最頂級の普惠型体系（Táng Luóの無双学院）もRén Zúにのみ門を開いた——異獣・植物霊・星球意志は全部「普惠」の外に排斥された。それは善意の遺漏ではなく、略奪派世界観の構造的必然である：「狩場宇宙観」において、我が族に非ざるは獲物か道具であり、共修者ではない。</p><p>衡元宙の万族全カバー基準の出す答えは：感元境はRén Zúの起点ではなく、万族の起点である；99%カバーはスローガンではなく、各族に一つの開かれた門があることである。</p><h2 id="五、五大核心落点" tabindex="-1">五、五大核心落点 <a class="header-anchor" href="#五、五大核心落点" aria-label="Permalink to &quot;五、五大核心落点&quot;">​</a></h2><ul><li>反エネルギー浪費：各族の天賦は希少資源であり、単一基準で万族を測ることこそ最大の大材小用</li><li>反略奪：差別化路線は全部循環と共生に基づき、他族本源を吞噬するものは一つもない</li><li>Táng Luó上限対比：種族狭隘な普惠は普惠ではなく恩賜である；恩賜の対象は永遠に「身内」のみ</li><li>万族全カバー：五大系譜＋奇特生命＋跨位面混血、感元境は万族99%全カバーに向けられる</li><li>超多元全開放：各族の感元法門は公開共有され、全開放鎖の第一環は種族を問わない</li></ul><h2 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to &quot;結論&quot;">​</a></h2><p>感元境の万族画卷は一つのことを証明した：宇宙の多様性は進化の障害ではなく、進化の燃料である。各族が自ら最も得意な方式で世界を感知し文明に還すとき、万族共生の宇宙は「差異を許す」から「差異を必要とする」へと進む——そしてこれこそ超多元衡錨境が成立する生命学的基礎である。</p><h2 id="関連" tabindex="-1">関連 <a class="header-anchor" href="#関連" aria-label="Permalink to &quot;関連&quot;">​</a></h2><ul><li>関連文書：<a href="./14-修炼境界统一划分.html">14-修炼境界统一划分</a> · <a href="./50-万族谱系总览.html">50-万族谱系总览</a> · <a href="./52-异族分类与共生.html">52-异族分类与共生</a> · <a href="./10-三百套本源修炼体系总览.html">10-三百套本源修炼体系总览</a></li><li>公式サイト：<a href="https://faker210.github.io/hengyuan-cosmos/zh/" target="_blank" rel="noreferrer">https://faker210.github.io/hengyuan-cosmos/zh/</a></li></ul>',25)])])}const p=a(d,[["render",i]]);export{c as __pageData,p as default};
